import json
import re

html_path = r'C:\Users\renu5\.gemini\antigravity\brain\e900d5b2-f367-42d4-9829-7fb6b2499468\.system_generated\steps\4\content.md'
with open(html_path, 'r', encoding='utf-8') as f:
    html = f.read()

# Extract all JSON arrays using regex
arrays_str = re.findall(r'\[\s*\[.*?\]\s*\]', html, re.DOTALL)

def extract_strings_from_any(obj):
    strings = []
    if isinstance(obj, str):
        if len(obj) > 20 and ' ' in obj and not obj.startswith('http') and '<html' not in obj and '<div' not in obj:
            strings.append(obj)
    elif isinstance(obj, list):
        for item in obj:
            strings.extend(extract_strings_from_any(item))
    elif isinstance(obj, dict):
        for val in obj.values():
            strings.extend(extract_strings_from_any(val))
    return strings

extracted = []
for s in arrays_str:
    try:
        # Some arrays might not be valid JSON if they contain JS expressions like `null` without quotes etc.
        # we can replace some common JS unquoted keys if necessary, but re.findall r'\[\s*\[.*?\]\s*\]' might catch valid JSON
        # Actually, Google's JSON is usually valid JSON but might have missing elements `[1,,2]`
        clean_s = re.sub(r',\s*,', ',null,', s)
        clean_s = re.sub(r'\[\s*,', '[null,', clean_s)
        clean_s = re.sub(r',\s*\]', ',null]', clean_s)
        data = json.loads(clean_s)
        extracted.extend(extract_strings_from_any(data))
    except Exception as e:
        pass

# If parsing fails, fallback to simple string literal extraction
if not extracted:
    strings = re.findall(r'"([^"\\]*(?:\\.[^"\\]*)*)"', html)
    for s in strings:
        # replace escaped chars
        s = s.encode('utf-8').decode('unicode_escape') if '\\' in s else s
        if len(s) > 20 and ' ' in s and not s.startswith('http') and '<html' not in s:
            extracted.append(s)

with open('all_strings.txt', 'w', encoding='utf-8') as out:
    for e in extracted:
        out.write(e + '\n\n')
print(f"Dumped {len(extracted)} strings.")
